test "all schema declarations encode decode and reject truncation" {
    inline for (.{
        SpiceLinkHeader,
        SpiceLinkMessage,
        SpiceLinkReply,
        SpiceLinkAuthMechanism,
        SpiceLinkEncryptedTicket,
        SpiceLinkResult,
        SpiceChannelID,
        SpiceMsgSetAck,
        SpiceMsgPing,
        SpiceMsgDisconnect,
        SpiceMsgcAckSync,
        SpiceMsgcAck,
        SpiceMsgcPong,
        SpiceMsgcDisconnect,
        SpiceMsgMainInit,
        SpiceMsgMainChannelsList,
        SpiceMsgMainMouseMode,
        SpiceMsgMainMultimediaTime,
        SpiceMsgcMainAttachChannels,
        SpiceMsgcMainMouseModeRequest,
        SpiceMsgDisplaySurfaceCreate,
        SpiceMsgDisplaySurfaceDestroy,
        SpiceMsgDisplayStreamActivateReport,
        SpiceMsgcDisplayStreamReport,
        SpiceMsgcDisplayInit,
        SpiceMsgcInputsKeyDown,
        SpiceMsgcInputsKeyUp,
        SpiceMsgcInputsKeyModifiers,
        SpiceMsgcInputsMouseMotion,
        SpiceMsgcInputsMousePosition,
        SpiceMsgcInputsMousePress,
        SpiceMsgcInputsMouseRelease,
        SpiceMsgInputsInit,
        SpiceMsgInputsKeyModifiers,
        SpiceMsgInputsMouseMotionAck,
    }) |T| {
        const zero: [T.minimum_wire_size]u8 = @splat(0);
        const value = try T.decodeExact(&zero);
        var writer: wire.Writer = .{ .allocator = std.testing.allocator, .limit = zero.len };
        defer writer.deinit();
        try value.encode(&writer);
        try std.testing.expectEqualSlices(u8, &zero, writer.bytes.items);
        for (0..zero.len) |end| {
            var reader = try wire.Reader.init(zero[0..end], 0);
            if (T.decode(&reader)) |_| return error.AcceptedTruncation else |_| {}
            try std.testing.expectEqual(@as(usize, 0), reader.offset);
        }
        const trailing = zero ++ [_]u8{0};
        try std.testing.expectError(error.TrailingBytes, T.decodeExact(&trailing));
    }
}
